shellCommands.command:
/bin/bash -lc "apply_patch \"*** Begin Patch
*** Update File: next.config.ts
@@
 import type { NextConfig } from 'next'

-const nextConfig: NextConfig = {}
+const nextConfig: NextConfig = {
+  experimental: {
+    authInterrupts: true,
+  },
+}

 export default nextConfig
*** End Patch\""

/bin/bash -lc "cat > app/admin/page.tsx <<'EOF'
import { forbidden } from 'next/navigation'

import { verifyAdmin } from '@/app/lib/auth'

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  if ("'!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session?.name}.</p>
      <p>You have access to admin-only resources.</p>
    </main>
  )
}
EOF'

/bin/bash -lc "cat > tsconfig.json <<'EOF'
{
  \"compilerOptions\": {
    \"target\": \"ES2017\",
    \"lib\": [\"dom\", \"dom.iterable\", \"esnext\"],
    \"allowJs\": true,
    \"skipLibCheck\": true,
    \"strict\": true,
    \"noEmit\": true,
    \"esModuleInterop\": true,
    \"module\": \"esnext\",
    \"moduleResolution\": \"bundler\",
    \"resolveJsonModule\": true,
    \"isolatedModules\": true,
    \"jsx\": \"react-jsx\",
    \"incremental\": true,
    \"plugins\": [
      {
        \"name\": \"next\"
      }
    ],
    \"paths\": {
      \"@/*\": [\"./*\"]
    }
  },
  \"include\": [\"next-env.d.ts\", \"**/*.ts\", \"**/*.tsx\", \".next/types/**/*.ts\"],
  \"exclude\": [\"node_modules\"]
}
EOF"
